SELECT ?zone ?tsId ?zoneName WHERE {
  ?zone rdfs:label ?zoneName .
  FILTER(?zoneName IN ("Core_bottom", "Perimeter_bot_ZN_4", "Perimeter_top_ZN_1"))
  ?zone a brick:Zone .
  OPTIONAL {
    ?sensor brick:pointLocation ?zone .
    ?sensor a brick:ElectricPowerSensor .
    ?sensor ref:hasTimeseriesId ?tsId .
  }
} LIMIT 200

SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "ZN") || LCASE(?label) LIKE "%core%" )
} LIMIT 200

SELECT ?label WHERE {
  ?z rdfs:label ?label .
  FILTER (?label LIKE "Core%" || ?label LIKE "Perimeter%")
} LIMIT 200

SELECT ?cls WHERE {
  ?s a ?cls .
  FILTER(?cls != rdf:Property)
} LIMIT 200

SELECT ?z ?label WHERE {
  ?z a brick:Zone ; rdfs:label ?label .
  FILTER (?label = "Core_bottom" || ?label = "Perimeter_bot_ZN_4" || ?label = "Perimeter_top_ZN_1")
} LIMIT 100

SELECT ?zone ?zoneLabel ?sensor ?sensorLabel ?prop WHERE {
  ?zone rdfs:label ?zoneLabel .
  FILTER (?zoneLabel = "Core_bottom" || ?zoneLabel = "Perimeter_bot_ZN_4" || ?zoneLabel = "Perimeter_top_ZN_1")
  ?sensor brick:pointLocation ?zone .
  OPTIONAL { ?sensor rdfs:label ?sensorLabel }
  OPTIONAL { ?sensor brick:hasPropertyType ?prop }
} LIMIT 100

